import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry depthwise_kx1_f32(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W,
    .param .u32 Ho,
    .param .u32 Wo,
    .param .u32 K,
    .param .u32 stride,
    .param .u32 pad,
    .param .u32 dil,
    .param .u32 has_bias
)
{
    .reg .u32 %r0, %r1, %r2, %r3, %r4, %r5, %r6, %r7, %r8, %r9, %r10;
    .reg .u32 %r11, %r12, %r13, %r14, %r15, %r16, %r17, %r18, %r19;
    .reg .s32 %s0, %s1, %s2, %s3, %s4, %s5, %s6, %s7, %s8, %s9;
    .reg .u64 %rd0, %rd1, %rd2, %rd3, %rd4, %rd5, %rd6, %rd7, %rd8, %rd9;
    .reg .u64 %rd10, %rd11, %rd12, %rd13, %rd14, %rd15, %rd16, %rd17, %rd18, %rd19;
    .reg .f32 %f0, %f1, %f2, %f3;
    .reg .pred %p0, %p1, %p2, %p3, %p4, %p5, %p6;

    ld.param.u64 %rd0, [in_ptr];
    ld.param.u64 %rd1, [wt_ptr];
    ld.param.u64 %rd2, [bias_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.u32 %r10, [C];
    ld.param.u32 %r11, [H];
    ld.param.u32 %r12, [W];
    ld.param.u32 %r13, [Ho];
    ld.param.u32 %r14, [Wo];
    ld.param.u32 %r15, [K];
    ld.param.u32 %r16, [stride];
    ld.param.u32 %r17, [pad];
    ld.param.u32 %r18, [dil];
    ld.param.u32 %r19, [has_bias];

    mov.u32 %r0, %ctaid.x;
    mov.u32 %r1, %ntid.x;
    mov.u32 %r2, %tid.x;
    mad.lo.u32 %r3, %r0, %r1, %r2;        // ow

    mov.u32 %r4, %ctaid.y;
    mov.u32 %r5, %ntid.y;
    mov.u32 %r6, %tid.y;
    mad.lo.u32 %r7, %r4, %r5, %r6;        // oh

    mov.u32 %r8, %ctaid.z;                // nc = n*C + c

    setp.ge.u32 %p0, %r3, %r14;
    @%p0 bra $done;
    setp.ge.u32 %p0, %r7, %r13;
    @%p0 bra $done;

    rem.u32 %r9, %r8, %r10;               // c

    cvt.s32.u32 %s0, %r3;
    cvt.s32.u32 %s1, %r16;
    cvt.s32.u32 %s2, %r17;
    mul.lo.s32 %s3, %s0, %s1;
    sub.s32 %s4, %s3, %s2;                // iw = ow*stride - pad
    cvt.s32.u32 %s5, %r12;
    setp.lt.s32 %p1, %s4, 0;
    setp.ge.s32 %p2, %s4, %s5;
    or.pred %p3, %p1, %p2;
    not.pred %p4, %p3;                    // valid_w

    cvt.s32.u32 %s6, %r7;
    mul.lo.s32 %s7, %s6, %s1;
    sub.s32 %s8, %s7, %s2;                // base_h = oh*stride - pad
    cvt.s32.u32 %s9, %r11;

    mov.f32 %f0, 0f00000000;              // acc
    cvt.u64.u32 %rd4, %r9;
    shl.b64 %rd5, %rd4, 2;
    add.s64 %rd6, %rd2, %rd5;             // bias + c
    setp.ne.u32 %p5, %r19, 0;
    @%p5 ld.global.f32 %f0, [%rd6];

    cvt.u64.u32 %rd7, %r8;
    cvt.u64.u32 %rd8, %r11;
    mul.lo.u64 %rd9, %rd7, %rd8;          // nc*H
    cvt.u64.u32 %rd10, %r12;              // W
    cvt.s64.s32 %rd11, %s4;               // iw

    cvt.u64.u32 %rd12, %r9;
    cvt.u64.u32 %rd13, %r15;
    mul.lo.u64 %rd14, %rd12, %rd13;       // c*K

    mov.u32 %r0, 0;                       // k
    mov.s32 %s3, %s8;                     // cur_h
$kloop:
    setp.lt.u32 %p0, %r0, %r15;
    @!%p0 bra $store;

    setp.lt.s32 %p1, %s3, 0;
    setp.ge.s32 %p2, %s3, %s9;
    or.pred %p3, %p1, %p2;
    not.pred %p6, %p3;
    and.pred %p6, %p6, %p4;               // valid tap

    cvt.s64.s32 %rd15, %s3;
    add.u64 %rd16, %rd9, %rd15;           // nc*H + ih
    mul.lo.u64 %rd16, %rd16, %rd10;       // *W
    add.u64 %rd16, %rd16, %rd11;          // + iw
    shl.b64 %rd16, %rd16, 2;
    add.s64 %rd17, %rd0, %rd16;

    cvt.u64.u32 %rd18, %r0;
    add.u64 %rd19, %rd14, %rd18;          // c*K + k
    shl.b64 %rd19, %rd19, 2;
    add.s64 %rd19, %rd1, %rd19;
    ld.global.f32 %f1, [%rd19];
    @%p6 ld.global.f32 %f2, [%rd17];
    @%p6 fma.rn.f32 %f0, %f1, %f2, %f0;

    cvt.s32.u32 %s0, %r18;
    add.s32 %s3, %s3, %s0;                // cur_h += dil
    add.u32 %r0, %r0, 1;
    bra $kloop;

$store:
    cvt.u64.u32 %rd4, %r8;
    cvt.u64.u32 %rd5, %r13;
    mul.lo.u64 %rd6, %rd4, %rd5;          // nc*Ho
    cvt.u64.u32 %rd7, %r7;
    add.u64 %rd6, %rd6, %rd7;             // + oh
    cvt.u64.u32 %rd8, %r14;
    mul.lo.u64 %rd6, %rd6, %rd8;          // *Wo
    cvt.u64.u32 %rd9, %r3;
    add.u64 %rd6, %rd6, %rd9;             // + ow
    shl.b64 %rd6, %rd6, 2;
    add.s64 %rd10, %rd3, %rd6;
    st.global.f32 [%rd10], %f0;

$done:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("depthwise_kx1_f32")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.conv2d = nn.Conv2d(in_channels, in_channels, kernel_size=(kernel_size, 1), stride=stride, padding=padding, dilation=dilation, groups=in_channels, bias=bias)
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        module = _get_ptx_module()
        n, c, h, w = x.shape
        k = self.kernel_size
        s = self.stride
        p = self.padding
        d = self.dilation
        ho = (h + 2 * p - d * (k - 1) - 1) // s + 1
        wo = (w + 2 * p - 1) // s + 1
        out = torch.empty((n, c, ho, wo), device=x.device, dtype=x.dtype)

        weight = self.conv2d.weight
        if self.conv2d.bias is None:
            bias_arg = weight
            has_bias = 0
        else:
            bias_arg = self.conv2d.bias
            has_bias = 1

        block_x = 32
        block_y = 8
        grid_x = (wo + block_x - 1) // block_x
        grid_y = (ho + block_y - 1) // block_y
        grid_z = n * c

        module.launch(
            "depthwise_kx1_f32",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, 1),
            arguments=[
                x,
                weight,
                bias_arg,
                out,
                i32(c),
                i32(h),
                i32(w),
                i32(ho),
                i32(wo),
                i32(k),
                i32(s),
                i32(p),
                i32(d),
                i32(has_bias),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

